  function tr(s) {
    var T = (window.AponarN3ExplainT && window.AponarN3ExplainT.map) || null;
    return T && Object.prototype.hasOwnProperty.call(T, s) ? T[s] : s;
  }
  function dynT(key, fallback) {
    try {
      if (window.AponarDyn) {
        var v = window.AponarDyn(key);
        if (v && v !== key) return v;
      }
    } catch (e) { /* fall through */ }
    return fallback;
  }
  function esc(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  var TOKEN = /([\u3400-\u9fff々〆ヵヶ][\u3400-\u9fff々〆ヵヶぁ-んァ-ンー]*)\[([ぁ-んァ-ンー]+)\]/g;
  function ruby(s) {
    var out = '', last = 0, m;
    TOKEN.lastIndex = 0;
    while ((m = TOKEN.exec(String(s)))) {
      out += esc(String(s).slice(last, m.index)) +
        '<ruby lang="ja">' + esc(m[1]) + '<rp>（</rp><rt>' + esc(m[2]) + '</rt><rp>）</rp></ruby>';
      last = m.index + m[0].length;
    }
    return out + esc(String(s).slice(last));
  }

  function buildBreakdown(entry) {
    var wrap = document.createElement('div');
    wrap.className = 'ex-explain';

    var head = document.createElement('div');
    head.className = 'ex-explain-head';
    var badge = document.createElement('span');
    badge.className = 'worked-badge';
    badge.textContent = dynT('qr.workedBadge', 'বাক্য ভেঙে বুঝুন');
    head.appendChild(badge);
    wrap.appendChild(head);

    if (entry.parts && entry.parts.length) {
      var grid = document.createElement('div');
      grid.className = 'sentence-parts';
      grid.setAttribute('aria-label', dynT('qr.sentenceParts', 'বাক্য অংশে ভাগ করে অর্থ'));
      entry.parts.forEach(function (p, i) {
        var cell = document.createElement('div');
        var idx = document.createElement('span');
        idx.className = 'part-index';
        idx.setAttribute('aria-hidden', 'true');
        idx.textContent = String(i + 1);
        var jp = document.createElement('p');
        jp.setAttribute('lang', 'ja');
        jp.innerHTML = ruby(p.japanese);
        var mn = document.createElement('p');
        mn.innerHTML = ruby(tr(p.meaning_bn));
        cell.append(idx, jp, mn);
        grid.appendChild(cell);
      });
      wrap.appendChild(grid);
    }

    if (entry.why_bn) {
      var why = document.createElement('p');
      why.className = 'example-why';
      var strong = document.createElement('strong');
      strong.textContent = dynT('qr.whyStructure', 'কেন এই গঠন?');
      why.appendChild(strong);
      why.appendChild(document.createTextNode(' '));
      var span = document.createElement('span');
      span.innerHTML = ruby(tr(entry.why_bn));
      why.appendChild(span);
      wrap.appendChild(why);
    }
    return wrap;
  }

  function enhance() {
    if (!DATA) return;
    var cards = document.querySelectorAll('article.card[id^="rule-"]');
    var done = 0;
    cards.forEach(function (card) {
      var id = card.id.replace('rule-', '');
      var list = DATA[id];
      if (!list) return;
      var rows = card.querySelectorAll('.examples10 .exrow');
      rows.forEach(function (row, i) {
        var entry = list[i];
        if (!entry || row.querySelector('.ex-explain')) return;
        row.appendChild(buildBreakdown(entry));
        done++;
      });
    });
    if (done !== 1130) {
      console.warn('TRY! N3 explain coverage', { rendered: done, expected: 1130 });
    }
  }

  function pageLang() {
    try {
      if (window.AponarDynLang) {
        var l = window.AponarDynLang();
        if (l) return l;
      }
    } catch (e) { /* fall through */ }
    var ok = { bn: 1, en: 1, ja: 1, vi: 1, ne: 1, hi: 1, ur: 1, my: 1, zh: 1, si: 1, fil: 1, id: 1, ar: 1, ml: 1 };
    var p = document.documentElement.getAttribute('data-language-preset');
    if (p && ok[p]) return p;
    var s = location.pathname.split('/').filter(Boolean)[0];
    if (s && ok[s]) return s;
    return document.documentElement.lang || 'bn';
  }

  function start() {
    if (pageLang() === 'bn' || window.AponarN3ExplainT) {
      enhance();
      return;
    }
    var tries = 0;
    var iv = setInterval(function () {
      tries++;
      if (window.AponarN3ExplainT || tries > 60) {
        clearInterval(iv);
        enhance();
      }
    }, 50);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', start, { once: true });
  } else {
    start();
  }
